 public static function text(mixed $v,int $max=1000,bool $optional=false):string {if(!is_string($v)||!preg_match('//u',$v))throw new ApiError(400,'Texto inválido.');$v=trim($v);if(class_exists('Normalizer'))$v=\Normalizer::normalize($v,\Normalizer::FORM_C);$length=function_exists('mb_strlen')?mb_strlen($v,'UTF-8'):preg_match_all('/./us',$v);if($length>$max||(!$optional&&$v==='')||preg_match('/[<>\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u',$v))throw new ApiError(400,'Revise os textos: não use HTML, campos vazios ou textos muito longos.');return $v;}
