 public static function config(mixed $input,array $hosts=[]):array {$keys=['name','brand','intro','description','button','color','questions','leadTitle','leadDescription','consent','privacy','resultTitle','resultDescription','offerLabel','offerUrl','webhook','defaultResultId'];$q=self::object($input,$keys,array_diff($keys,['defaultResultId']));$out=['defaultResultId'=>isset($q['defaultResultId'])?self::uuid($q['defaultResultId']):self::id()];foreach(['name','brand','intro','button','leadTitle','resultTitle','offerLabel'] as $key)$out[$key]=self::text($q[$key],$key==='name'?120:300);foreach(['description','leadDescription','consent','resultDescription'] as $key)$out[$key]=self::text($q[$key],2000,$key!=='consent');if(!is_string($q['color'])||!preg_match('/^#[a-f0-9]{6}$/iD',$q['color']))throw new ApiError(400,'Cor inválida.');$out['color']=strtolower($q['color']);$out['privacy']=self::url($q['privacy']);$out['offerUrl']=self::url($q['offerUrl']);$out['webhook']=self::url($q['webhook'],$hosts);if(!is_array($q['questions'])||!array_is_list($q['questions'])||count($q['questions'])<1||count($q['questions'])>60)throw new ApiError(400,'Use de 1 a 60 etapas.');$seen=[$out['defaultResultId']=>true];
 $unique=function($id=null)use(&$seen){$id=$id===null?self::id():self::uuid($id);if(isset($seen[$id]))throw new ApiError(400,'Identificador repetido.');$seen[$id]=true;return $id;};$out['questions']=[];
 foreach($q['questions'] as $raw){self::object($raw,['id','type','title','options','optionIds','points','routes','next','description','duration','offerLabel','offerUrl'],['title']);$type=$raw['type']??'question';if(!in_array($type,['question','text','loading','result'],true))throw new ApiError(400,'Tipo de etapa inválido.');$s=['id'=>$unique($raw['id']??null),'type'=>$type,'title'=>self::text($raw['title'],500)];
 if($type==='question'){if(!isset($raw['options'])||!is_array($raw['options'])||!array_is_list($raw['options'])||count($raw['options'])<2||count($raw['options'])>12)throw new ApiError(400,'Use de 2 a 12 opções.');foreach(['optionIds','points','routes'] as $key)if(isset($raw[$key])&&(!is_array($raw[$key])||!array_is_list($raw[$key])||count($raw[$key])!==count($raw['options'])))throw new ApiError(400,'Opções e regras desalinhadas.');foreach($raw['options'] as $i=>$value){$s['options'][]=self::text($value,300);$s['optionIds'][]=$unique($raw['optionIds'][$i]??null);$s['points'][]=self::integer($raw['points'][$i]??0,0,100);$s['routes'][]=$raw['routes'][$i]??'';}if(isset($raw['next']))$s['next']=$raw['next'];}
