 if($type==='result'){$s['description']=self::text($raw['description']??'',2000,true);$s['offerLabel']=self::text(($raw['offerLabel']??'')?:$out['offerLabel'],300);$s['offerUrl']=self::url($raw['offerUrl']??'');}$out['questions'][]=$s;}
