 public static function initial(string $mode,int|null $now=null):array {return ['page'=>'start','history'=>[],'answers'=>[],'pending'=>null,'captured'=>false,'enteredAt'=>$now??self::now(),'mode'=>$mode,'complete'=>false];}
 public static function now():int {return (int)floor(microtime(true)*1000);}
 public static function stage(array $q,string $id):?array {foreach($q['questions'] as $s)if($s['id']===$id)return $s;return null;}
 private static function destination(array $q,array $s,string $target):string {if($target==='lead')return 'lead';if($target==='result')return 'default';if($target!=='')return $target;$i=array_search($s['id'],array_column($q['questions'],'id'),true);return $q['questions'][$i+1]['id']??'lead';}
 private static function go(array $q,array &$state,string $to,int $now):void {if(($to==='default'||(self::stage($q,$to)['type']??'')==='result')&&!$state['captured']){$state['pending']=$to;$to='lead';}$state['history'][]=$state['page'];$state['page']=$to;$state['enteredAt']=$now;if($state['captured']&&($to==='default'||(self::stage($q,$to)['type']??'')==='result'))$state['complete']=true;}
 public static function action(array $q,array $state,mixed $input,int|null $now=null):array {$input=self::object($input,['version','action','optionId','text'],['version','action']);self::integer($input['version'],0,100000);$now??=self::now();$action=$input['action'];if(!in_array($action,['start','answer','advance','back'],true)||((isset($input['optionId'])||isset($input['text']))&&$action!=='answer'))throw new ApiError(400,'Ação inválida.');if($state['complete'])throw new ApiError(409,'Esta sessão já foi concluída.');$s=self::stage($q,$state['page']);
 if($action==='back'){if(!$state['history'])throw new ApiError(409,'Não há etapa anterior.');$to=array_pop($state['history']);unset($state['answers'][$state['page']],$state['answers'][$to]);$state['page']=$to;$state['pending']=null;$state['enteredAt']=$now;return $state;}
 if($state['page']==='start'&&$action==='start'){self::go($q,$state,$q['questions'][0]['id'],$now);return $state;}
 if(($s['type']??'')==='question'&&$action==='answer'){if(array_key_exists('text',$input))throw new ApiError(400,'Esta etapa exige uma opção.');$id=self::uuid($input['optionId']??null);$index=array_search($id,$s['optionIds'],true);if($index===false)throw new ApiError(400,'Esta opção não pertence à etapa atual.');$state['answers'][$s['id']]=$id;self::go($q,$state,self::destination($q,$s,$s['routes'][$index]?:($s['next']??'')),$now);return $state;}
 if(($s['type']??'')==='text'&&$action==='answer'){if(array_key_exists('optionId',$input))throw new ApiError(400,'Esta etapa exige uma resposta em texto.');$answer=self::text($input['text']??null,2000);$state['answers'][$s['id']]=$answer;self::go($q,$state,self::destination($q,$s,$s['next']),$now);return $state;}
 if(($s['type']??'')==='loading'&&$action==='advance'){if($now-$state['enteredAt']<$s['duration']*1000)throw new ApiError(409,'Aguarde o carregamento terminar.');self::go($q,$state,self::destination($q,$s,$s['next']),$now);return $state;}throw new ApiError(409,'Ação não permitida nesta etapa.');
 }
 public static function answers(array $q,array $state):array {$out=[];foreach($state['answers'] as $id=>$optionId){$s=self::stage($q,$id);if(($s['type']??'')==='text'){$out[]=['stageId'=>$id,'optionId'=>null,'question'=>$s['title'],'answer'=>self::text($optionId,2000),'points'=>0,'type'=>'text'];continue;}$i=$s?array_search($optionId,$s['optionIds']??[],true):false;if($i===false)throw new ApiError(500,'Resposta persistida inválida.');$out[]=['stageId'=>$id,'optionId'=>$optionId,'question'=>$s['title'],'answer'=>$s['options'][$i],'points'=>$s['points'][$i]];}return $out;}
 public static function contact(mixed $input):array {$v=self::object($input,['version','name','email','phone','consent'],['version','name','email','phone','consent']);self::integer($v['version'],0,100000);$out=['name'=>self::text($v['name'],150),'email'=>strtolower(self::text($v['email'],254)),'phone'=>preg_replace('/[() .-]/','',self::text($v['phone'],25)),'consent'=>true];if($v['consent']!==true||!filter_var($out['email'],FILTER_VALIDATE_EMAIL)||!preg_match('/^\+?\d{8,15}$/D',$out['phone']))throw new ApiError(400,'Revise o e-mail, o WhatsApp e o consentimento.');return $out;}
 public static function complete(array $q,array $state,int|null $now=null):array {if($state['page']!=='lead'||$state['captured']||$state['complete'])throw new ApiError(409,'Contato não permitido nesta etapa.');$state['captured']=true;self::go($q,$state,$state['pending']??'default',$now??self::now());return $state;}
 public static function view(string $id,int $version,array $q,array $state,int|null $now=null):array {$now??=self::now();$out=['id'=>$id,'version'=>$version,'brand'=>$q['brand'],'color'=>$q['color'],'mode'=>$state['mode'],'canBack'=>(bool)$state['history']&&!$state['complete']];$s=self::stage($q,$state['page']);if($state['page']==='start')return $out+['kind'=>'start','title'=>$q['intro'],'description'=>$q['description'],'button'=>$q['button']];if($state['page']==='lead')return $out+['kind'=>'lead','title'=>$q['leadTitle'],'description'=>$q['leadDescription'],'consent'=>$q['consent'],'privacy'=>$q['privacy']];if(($s['type']??'')==='question')return $out+['kind'=>'question','stageId'=>$s['id'],'title'=>$s['title'],'options'=>array_map(fn($label,$i)=>['id'=>$s['optionIds'][$i],'label'=>$label],$s['options'],array_keys($s['options']))];if(($s['type']??'')==='text')return $out+['kind'=>'text','stageId'=>$s['id'],'title'=>$s['title'],'description'=>$s['description'],'maxLength'=>2000];if(($s['type']??'')==='loading')return $out+['kind'=>'loading','stageId'=>$s['id'],'title'=>$s['title'],'description'=>$s['description'],'remainingMs'=>max(0,$s['duration']*1000-($now-$state['enteredAt']))];if($state['complete'])return $out+['kind'=>'result','stageId'=>$s['id']??$q['defaultResultId'],'title'=>$s['title']??$q['resultTitle'],'description'=>$s['description']??$q['resultDescription'],'offerLabel'=>$s['offerLabel']??$q['offerLabel'],'offerUrl'=>$s['offerUrl']??$q['offerUrl'],'score'=>array_sum(array_column(self::answers($q,$state),'points'))];throw new ApiError(500,'Estado inválido.');}
 public static function slug(mixed $slug):string {if(!is_string($slug)||!preg_match('/^quiz-[1-9][0-9]{0,8}$/D',$slug))throw new ApiError(400,'Endereço de quiz inválido.');return $slug;}
